alter table public.estimates add column if not exists sent_at timestamptz, add column if not exists expires_at timestamptz, add column if not exists follow_up_at timestamptz, add column if not exists declined_at timestamptz, add column if not exists decline_reason text, add column if not exists converted_job_id uuid references public.jobs(id) on delete set null;
create index if not exists idx_estimates_follow_up on public.estimates(follow_up_at) where status in ('draft','sent');
create index if not exists idx_estimates_converted_job on public.estimates(converted_job_id) where converted_job_id is not null;
create or replace function private.estimate_sales_dashboard() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('view_estimates') then raise exception 'Estimate permission required'; end if; return jsonb_build_object('draft',(select count(*) from public.estimates where status='draft'),'sent',(select count(*) from public.estimates where status='sent'),'approved',(select count(*) from public.estimates where status='approved'),'followUpDue',(select count(*) from public.estimates where status in ('draft','sent') and follow_up_at is not null and follow_up_at<=now()),'openValue',(select coalesce(sum(o.price),0) from public.estimates e join public.estimate_options o on o.estimate_id=e.id where e.status in ('draft','sent')),'approvedValue',(select coalesce(sum(o.price),0) from public.estimates e join public.estimate_options o on o.id=e.approved_option_id where e.status='approved')); end $$;
create or replace function public.estimate_sales_dashboard() returns jsonb language sql stable set search_path='' as $$ select private.estimate_sales_dashboard() $$; revoke all on function public.estimate_sales_dashboard() from public,anon; grant execute on function public.estimate_sales_dashboard() to authenticated;